// Extrai o JSON dos casos da resposta da IA (modelos de raciocínio, como o DeepSeek R1,
// escrevem um bloco <think> antes) e normaliza para o contrato do QA Hub.
const out = $input.first().json;
let text = String(out.text ?? out.output ?? out.response ?? '');
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/```(?:json)?/gi, '').trim();
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start < 0 || end <= start) throw new Error('A IA não devolveu JSON: ' + text.slice(0, 200));
// Modelos às vezes quebram linha "de verdade" dentro das strings do JSON: escapa.
let json = '', inString = false, escaped = false;
for (const ch of text.slice(start, end + 1)) {
  if (inString && !escaped && (ch === '\n' || ch === '\r' || ch === '\t')) {
    json += ch === '\n' ? '\\n' : ch === '\r' ? '' : '\\t';
    continue;
  }
  if (ch === '"' && !escaped) inString = !inString;
  escaped = ch === '\\' && !escaped;
  json += ch;
}
let data;
try {
  data = JSON.parse(json);
} catch (e) {
  throw new Error('JSON inválido na resposta da IA: ' + e.message);
}
const list = Array.isArray(data) ? data : (data.cases || []);
const cases = list
  .filter((c) => c && c.title && (c.gherkin || c.steps))
  .map((c) => ({
    title: String(c.title).trim(),
    priority: String(c.priority || 'média').toLowerCase(),
    kind: String(c.kind || 'positivo').toLowerCase(),
    gherkin: String(c.gherkin || c.steps).trim(),
  }));
if (!cases.length) throw new Error('Nenhum caso válido na resposta da IA');
return [{ json: { cases } }];
